from pathlib import Path
import hashlib,json
root=Path('/workspace/capiro-followup')
scan=json.loads(Path('/tmp/capiro-followup-qualification/architecture-preflight.json').read_text())
reasons={
'CalendarEvents':"One event viewport owns agenda/grid choice and their loading, error, empty and search presentation. Meetings status is now adjacent to the agenda table so healthy independent sources survive; grids keep the existing meeting gate. Normalization, reads and meeting editors retain separate owners. Root and independent core_intake reviewed full source and scoped evidence; see docs/followup-20261012/STRUCTURE-REVIEW.md.",
'useCalendar':"One Calendar screen model composes validated URL date/view selection, current shared-verified client scope, filters and fixed-operation reads. Calendar-local selection.ts validates presentation hints; range and extra-feed loading retain separate owners. URL history preserves view/date through the shared disposal boundary without retaining former scope data or drafts. Root and independent core_intake accepted correction076ee3e after three red controls and28 scoped browser passes; no second authority or transport. See docs/followup-20261012/STRUCTURE-REVIEW.md.",
'PlannerScreen':"One public Planner entry composes section navigation and current bootstrap. LinkedTaskDetail is the separate narrow owner of task URL resolution, current ID/client presentation checks, retry and dismissal; existing TaskDetail remains canonical. All content stays behind the current bootstrap gate. Root and independent core_intake reviewed scope and history controls; no new transport or authorization behavior in this composition. See docs/followup-20261012/STRUCTURE-REVIEW.md.",
'useTaskWorkspace':"The existing task workspace owns its related list query, local filters, selection and batch actions. A narrow shared taskMatchesClient predicate replaces inline client/project membership logic and is characterized as direct-client OR current-project association, not backend authorization. TaskFilters remains byte-identical to the frozen base and renders only this workspace's controls; its whole-file review is renewed for the sibling change. Root and independent core_intake reviewed both complete functions. See docs/followup-20261012/STRUCTURE-REVIEW.md.",
'ProspectFileSession':"One keyed actor/tenant/prospect view composes the existing authorized file list, readiness-gated links and separate upload recovery hook. The added filename search, clear and no-match presentation consume only the current successful non-fetching list and reset with the existing scope. No new transport, cache, authority or corpus ownership is introduced. Root inspected the full function and phone capture; independent calendar_relationships accepted its bounded source/test evidence. See docs/followup-20261012/STRUCTURE-REVIEW.md.",
'MailCompose':"One composer owns recipient/body controls and the frozen send-review snapshot. SignaturePreview separately owns adopted DOMPurify/sandbox presentation; useMailRewrite owns local rewrite/Undo lifetime. Only current successful non-fetching signature HTML enters the display snapshot; loading/unavailable state remains explicit and appendSignature keeps backend send semantics without copying preview HTML into bodyHtml. Root and independent prospects reviewed the stale-refetch correction and full361-line function. No new provider, transport or actor resolver is embedded here. See docs/followup-20261012/STRUCTURE-REVIEW.md.",
'useMailRewrite':"One source-bound rewrite lifecycle owns the current body, pending attempt and one prior-body Undo snapshot. Manual edits, source/recipient changes, identity invalidation and unmount revoke the coupled state; Undo rechecks the existing captured authority and issues no request. The native request/schema/conversion retain rewrite.ts ownership. Splitting Undo into another hook would duplicate lifetime and cache subscriptions. Root and independent prospects reviewed full161-line function and meaningful authority controls. See docs/followup-20261012/STRUCTURE-REVIEW.md.",
'WorkPage':"One current-client read-only Work composition shows current Strategy projections and the separate Workspace document view. The existing fixed tenantMembers read supplies labels through a pure exact-Clerk resolver with canonical derived type; missing or ambiguous roster data is unavailable, only null ownership unassigned. Source failures stay independent, while shared query/ApplicationBoundary own cancellation and expiry. Upcoming status is a supplied node field. Root and independent core_intake reviewed full226-line function, final8f2f499 bytes and owner/status controls. See docs/followup-20261012/STRUCTURE-REVIEW.md."
}
explicitPath=root/'scripts/architecture/reviewed-size-findings.json';explicit=json.loads(explicitPath.read_text())
modulePath=root/'docs/architecture-size-reviews.json';modules=json.loads(modulePath.read_text())
for finding in scan['sizeFindings']:
 if not finding['blocking'] or '/portfolio/' not in finding['file']:continue
 assert finding['symbol'] in reasons
 matches=[r for r in explicit if (r['file'],r['kind'],r['symbol'])==(finding['file'],finding['kind'],finding['symbol'])];assert len(matches)==1
 matches[0].update(fingerprint=finding['fingerprint'],reason=reasons[finding['symbol']],reviewedBy='Codex shared frontend integration owner with independent assigned-lane source review',reviewedOn='2026-10-12')
for file in sorted({f['file'] for f in scan['sizeFindings'] if f['blocking'] and '/modules/' in f['file']}):
 findings=[f for f in scan['sizeFindings'] if f['file']==file]
 symbol=findings[0]['symbol'];assert symbol in reasons
 record={'path':file,'sha256':hashlib.sha256((root/file).read_bytes()).hexdigest(),'reviewer':'Codex shared frontend integration owner and independent core_intake source review','reviewedAt':'2026-10-12','evidence':'docs/followup-20261012/STRUCTURE-REVIEW.md#modules-presentation','rationale':reasons[symbol],'functions':[{'name':f['symbol'],'nonblankLines':f['nonblank']} for f in findings if f['kind']=='function'],'signals':[f"{file}: function over80 nonblank lines requires review" if f['kind']=='function' else f"{file}: {f['nonblank']} nonblank lines require review" for f in findings]}
 matches=[i for i,r in enumerate(modules) if r['path']==file];assert len(matches)<2
 if matches:modules[matches[0]]=record
 else:modules.append(record)
explicitPath.write_text(json.dumps(explicit,indent=2)+'\n');modulePath.write_text(json.dumps(modules,indent=2)+'\n')
print('Registered9 individually reviewed signals in their existing canonical owners; no scanner or transfer-baseline change.')
